from __future__ import absolute_import
from selenium.webdriver.common.by import By
# from taf.selenium.gnb.oam.core.common import PagePart
# from taf.selenium.gnb.oam.core.exceptions import CouldNotFindObject
from taf.selenium.core.common import PagePart
from taf.selenium.core.exceptions import CouldNotFindObject


class LoginPage(PagePart):

    def __init__(self, driver):
        super(LoginPage, self).__init__(driver)

    def enter_username(self, locator, username, timeout=60):
        self.insert_text_to_enabled_element(locator, username, timeout)

    def enter_password(self, locator, password, timeout=60):
        self.insert_text_to_enabled_element(locator, password, timeout)

    def click_login(self, locator, timeout=60):
        self.click_enabled_element(locator, timeout)


class NomLoginPage(LoginPage):
    """
    A class manages login page, login function included.
    """

    def __init__(self, driver):
        super(NomLoginPage, self).__init__(driver)
        self._driver = driver

    _INPUT_USERNAME_XPATH = '//input[@name="username"]'
    _INPUT_PASSWORD_XPATH = '//input[@name="password"]'
    _LOGIN_BUTTON_XPATH = '//input[@name="login"]'
    _ACCEPT_BUTTON_XPATH = '//*[@id="legal_disclaimer_dialog_accept_button-content"]'
    # _OBJECTS_PAGE_XPATH = '//div[@data-key="network-view" and contains(@style, "position: fixed")]'
    _PAGE_LOAD_FINISH_XPATH = '//div[@data-key and contains(@style, "position: fixed")]'
    _WELCOME_PAGE_CLOSE_BUTTON = '//div[@id="closeLanding-content"]'
    _ACCEPT_BUTTON_XPATH_ex = '//*[@id="legal_disclaimer_dialog_accept_button"]'
    _WELCOME_PAGE_CLOSE_BUTTON_ex = 'landing-page-close-button'

    def login(self, username, password, timeout=60):
        """
        Login into NOM Webui.

        :param username: str, username
        :param password: str, password
        :param timeout: int, timeout for the element be available to click
        """
        if self.element_exists((By.XPATH, self._INPUT_USERNAME_XPATH), timeout) and \
                self.element_exists((By.XPATH, self._INPUT_PASSWORD_XPATH), timeout) and \
                self.element_exists((By.XPATH, self._LOGIN_BUTTON_XPATH), timeout):
            self.enter_username((By.XPATH, self._INPUT_USERNAME_XPATH), username, timeout)
            self.enter_password((By.XPATH, self._INPUT_PASSWORD_XPATH), password, timeout)
            # self.click_login((By.XPATH, "//*[@id='pro-fam-name']"), timeout)
            self.click_login((By.XPATH, self._LOGIN_BUTTON_XPATH), timeout)

        else:
            raise CouldNotFindObject(
                "Login page not opened or could not find username/password input box or login button")
        if self.element_exists((By.XPATH, self._ACCEPT_BUTTON_XPATH), 20):
            self.click_button((By.XPATH, self._ACCEPT_BUTTON_XPATH))
        if self.element_exists((By.XPATH, self._ACCEPT_BUTTON_XPATH_ex), 20):
            self.click_button((By.XPATH, self._ACCEPT_BUTTON_XPATH_ex))
        if self.element_exists((By.XPATH, self._WELCOME_PAGE_CLOSE_BUTTON), 20):
            self.click_button((By.XPATH, self._WELCOME_PAGE_CLOSE_BUTTON))
        if self.element_exists((By.ID, self._WELCOME_PAGE_CLOSE_BUTTON_ex), 20):
            self.click_button((By.ID, self._WELCOME_PAGE_CLOSE_BUTTON_ex))
        self.wait_for_enable((By.XPATH, '//*[@id="user-account-summary-button"]'))
        self.wait_for_visibility((By.XPATH, self._PAGE_LOAD_FINISH_XPATH), 120)


class LogoutPage(PagePart):
    """
    A class manages logout page, logout function included.
    """
    _USER_ACCOUNT_VIEW_XPATH = '//*[@id="user-account-summary-button"]'
    _LOGOUT_BUTTON_XPATH = '//div[contains(@class, "styles__UserAccountSummaryFooter")]'

    def logout(self, timeout=60):
        """
        Logout from nom web.

        :param int timeout: timeout for the element be available to click
        """
        try:
            self.click_enabled_element((By.XPATH, self._USER_ACCOUNT_VIEW_XPATH), timeout)
            self.click_enabled_element((By.XPATH, self._LOGOUT_BUTTON_XPATH), timeout)
            self.close_browser()
        except Exception:
            self.click_enabled_element((By.XPATH, self._USER_ACCOUNT_VIEW_XPATH), timeout)
            self.click_enabled_element((By.XPATH, self._LOGOUT_BUTTON_XPATH), timeout)
            self.close_browser()
